using System;

public static class TextureMemory
{
    private const int AstcBlockBytes = 16; // 블록 하나 = 128비트, 블록 크기와 무관

    public static int MipCount(int width, int height, bool mipmaps)
    {
        CheckSize(width, height);
        if (!mipmaps) return 1;
        int count = 1;
        while (width > 1 || height > 1)
        {
            width = NextMip(width);
            height = NextMip(height);
            count++;
        }
        return count;
    }

    public static long UncompressedBytes(int width, int height, int bitsPerPixel, bool mipmaps)
    {
        CheckSize(width, height);
        if (bitsPerPixel <= 0 || bitsPerPixel % 8 != 0)
            throw new ArgumentOutOfRangeException(nameof(bitsPerPixel));

        long bytesPerPixel = bitsPerPixel / 8;
        long total = 0;
        while (true)
        {
            // long 으로 올린 뒤 곱한다: 16384 * 16384 * 8 은 int 범위를 넘는다.
            total += (long)width * height * bytesPerPixel;
            if (!mipmaps || (width == 1 && height == 1)) break;
            width = NextMip(width);
            height = NextMip(height);
        }
        return total;
    }

    public static long AstcBytes(int width, int height, int blockWidth, int blockHeight, bool mipmaps)
    {
        CheckSize(width, height);
        CheckBlock(blockWidth, blockHeight);

        long total = 0;
        while (true)
        {
            // 블록 수는 올림: 가장자리에 걸친 픽셀도 블록 하나를 통째로 쓴다.
            long blocksX = ((long)width + blockWidth - 1) / blockWidth;
            long blocksY = ((long)height + blockHeight - 1) / blockHeight;
            total += blocksX * blocksY * AstcBlockBytes;
            if (!mipmaps || (width == 1 && height == 1)) break;
            width = NextMip(width);
            height = NextMip(height);
        }
        return total;
    }

    public static double AstcBitsPerPixel(int blockWidth, int blockHeight)
    {
        CheckBlock(blockWidth, blockHeight);
        return 128.0 / ((double)blockWidth * blockHeight);
    }

    // 다음 밉 레벨의 한 변: 정수 절반, 최소 1.
    private static int NextMip(int size) => size > 1 ? size / 2 : 1;

    private static void CheckSize(int width, int height)
    {
        if (width <= 0) throw new ArgumentOutOfRangeException(nameof(width));
        if (height <= 0) throw new ArgumentOutOfRangeException(nameof(height));
    }

    private static void CheckBlock(int blockWidth, int blockHeight)
    {
        if (blockWidth <= 0) throw new ArgumentOutOfRangeException(nameof(blockWidth));
        if (blockHeight <= 0) throw new ArgumentOutOfRangeException(nameof(blockHeight));
    }
}

